#!/usr/bin/env python3
"""Generate ui/Grassfield/Ui/Tokens.qml, and the compositor plugin's token header, from ui/tokens/tokens.json (stdlib only).

Usage: gen-tokens.py [--check]
  --check  do not write; exit 1 if a generated file is stale.

The compositor plugin draws with its own renderer: the groups in PLUGIN_GROUPS are also written as C++ constants to
compositor/src/core/ThemeTokens.hpp (numbers, and colours as 0xRRGGBB), read by compositor/src/core/Theme.hpp (ADR-0003:
one source of values for both renderers; ADR-0015).
"""
import json
import pathlib
import re
import sys

UI = pathlib.Path(__file__).resolve().parent.parent
SRC = UI / "tokens" / "tokens.json"
DST = UI / "Grassfield" / "Ui" / "Tokens.qml"
PLUGIN_DST = UI.parent / "compositor" / "src" / "core" / "ThemeTokens.hpp"
PLUGIN_GROUPS = ("titlebar",)


def is_leaf(node):
    return isinstance(node, dict) and "value" in node


def qml_literal(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(value)


def qml_type(value):
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "real"
    if isinstance(value, str):
        return "string"
    return "var"


def camel(*parts):
    first, *rest = parts
    return first + "".join(p[:1].upper() + p[1:] for p in rest)


def generate(data):
    out = [
        "pragma Singleton",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "import QtQml",
        "",
        "QtObject {",
        f"    readonly property int version: {data['version']}",
    ]
    for group, body in data.items():
        if group in ("version", "_note"):
            continue
        if group == "color":
            for appearance, roles in body.items():
                out.append("")
                out.append(f"    // color roles, {appearance} appearance")
                out.append(f"    readonly property var {camel('color', appearance)}: ({{")
                items = list(roles.items())
                for i, (role, leaf) in enumerate(items):
                    comma = "," if i < len(items) - 1 else ""
                    out.append(f"        {role}: {qml_literal(leaf['value'])}{comma}  // {leaf['source']}")
                out.append("    })")
            continue
        out.append("")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            v = leaf["value"]
            expr = qml_literal(v)
            typ = qml_type(v)
            # Optional leaf keys make a token follow an Appearance setting (Settings > Accessibility > Display):
            #   "textScale": true        the size is scaled by Appearance.textScale and rounded (Text Size)
            #   "increaseContrast": V    the value is V while Appearance.increaseContrast is on (Increase Contrast)
            if leaf.get("textScale"):
                expr = f"Math.round({expr} * Appearance.textScale)"
                typ = "int"
            if "increaseContrast" in leaf:
                expr = f"Appearance.increaseContrast ? {qml_literal(leaf['increaseContrast'])} : {expr}"
            out.append(f"    // {leaf['source']}")
            out.append(f"    readonly property {typ} {camel(group, name)}: {expr}")
    out.append("}")
    return "\n".join(out) + "\n"


def cpp_constant(group, name, value):
    """One C++ constant of a plugin token: kGroupName, int / double / 0xRRGGBB colour."""
    ident = "k" + camel(group, name)[:1].upper() + camel(group, name)[1:]
    if isinstance(value, bool):
        return f"inline constexpr bool {ident} = {'true' if value else 'false'};"
    if isinstance(value, int):
        return f"inline constexpr int {ident} = {value};"
    if isinstance(value, float):
        return f"inline constexpr double {ident} = {value!r};"
    if isinstance(value, str) and re.fullmatch(r"#[0-9A-Fa-f]{6}", value):
        return f"inline constexpr uint32_t {ident} = 0x{value[1:].upper()};"
    raise SystemExit(f"tokens.json: {group}.{name}: a plugin token is a number or a #rrggbb colour")


def generate_plugin(data):
    out = [
        "#pragma once",
        "",
        "// GENERATED by ui/tools/gen-tokens.py from ui/tokens/tokens.json. Do not edit.",
        "// The design tokens the compositor plugin draws with (read by core/Theme.hpp; no Hyprland include).",
        "",
        "#include <cstdint>",
        "",
        "namespace gf::theme::tokens {",
    ]
    for group in PLUGIN_GROUPS:
        body = data.get(group)
        if not isinstance(body, dict):
            raise SystemExit(f"tokens.json: plugin group {group} is missing")
        for name, leaf in body.items():
            if not is_leaf(leaf):
                raise SystemExit(f"tokens.json: {group}.{name} is not a {{value, source}} leaf")
            out.append(f"    // {leaf['source']}")
            out.append(f"    {cpp_constant(group, name, leaf['value'])}")
    out.append("} // namespace gf::theme::tokens")
    return "\n".join(out) + "\n"


# Provenance (audit GF-095): every token says where its value comes from, with a pointer a reviewer can follow: the F1
# reference analysis, a spec, an ADR, a test, the master prompt or an audit. A bare "estimate" is not a source.
REPO = UI.parent
F1 = REPO / "docs" / "testing" / "f1-reference-gaps.md"
PATH_CITE = re.compile(r"(?:docs|tests)/[A-Za-z0-9_./-]+\.(?:md|py|qml|sh|json)")
ADR_CITE = re.compile(r"ADR-(\d{4})")
# A section pointer has one form: `<file> \u00a7 <section>` (docs/**.md or master-prompt), ended by ";" or "]".
SECTION_CITE = re.compile(r"(docs/[A-Za-z0-9_./-]+\.md|master-prompt) \u00a7 ([^;\]]+)")
# `ADR-0016 section 5`: the number of a numbered heading of that ADR.
ADR_SECTION_CITE = re.compile(r"ADR-(\d{4}) section (\d+(?:\.\d+)?)")


def headings_of(path):
    """Heading names (## and ###) of a markdown file, lower-case, the parenthetical tail dropped, and their numbers ('5.5')."""
    names, numbers = [], set()
    for line in path.read_text().splitlines():
        m = re.match(r"#{1,4} (.+)", line)
        if not m:
            continue
        text = m.group(1).strip()
        number = re.match(r"(\d+(?:\.\d+)?)\.?(?:\s|$)", text)
        if number:
            numbers.add(number.group(1))
        names.append(re.sub(r"\s*\(.*$", "", text).strip().lower())
    return names, numbers


def f1_headings():
    return headings_of(F1)[0]


def section_resolves(text, headings):
    """'Window chrome, Dock and Menus and popovers' must be made of real headings (longest first), joined by ', ' or ' and '."""
    rest = re.sub(r"\s*\(.*?\)", "", text).strip().lower()
    by_length = sorted(headings, key=len, reverse=True)
    while rest:
        for name in by_length:
            if rest.startswith(name):
                rest = rest[len(name):]
                rest = re.sub(r"^(?:,\s*| and )", "", rest)
                break
        else:
            return False
    return True


def source_problems(source, headings):
    """Why a token source is not a followable pointer (empty list: it is)."""
    problems = []
    cited = False
    for path in PATH_CITE.findall(source):
        cited = True
        if not (REPO / path).exists():
            problems.append("cites %s, which does not exist" % path)
    for number in ADR_CITE.findall(source):
        cited = True
        if not list((REPO / "docs" / "decisions").glob("ADR-%s*" % number)):
            problems.append("cites ADR-%s, which does not exist" % number)
    for number, section in ADR_SECTION_CITE.findall(source):
        files = list((REPO / "docs" / "decisions").glob("ADR-%s*" % number))
        if files and section not in headings_of(files[0])[1]:
            problems.append("cites section %s of ADR-%s, which has no such numbered heading" % (section, number))
    for path, section in SECTION_CITE.findall(source):
        cited = True
        while section.count(")") > section.count("("):  # the ")" that closes a sentence around the pointer
            section = section[:section.rindex(")")]
        section = section.strip()
        target = REPO / ("docs/master-prompt.md" if path == "master-prompt" else path)
        if not target.exists():
            continue  # reported above as a missing path
        names, numbers = headings_of(target)
        if path.endswith("f1-reference-gaps.md"):
            ok = section_resolves(section, names)
        elif path == "master-prompt":
            lead = re.match(r"\d+(?:\.\d+)?", section)
            ok = bool(lead) and lead.group(0) in numbers
        else:
            ok = any(name.startswith(section.lower()) for name in names)
        if not ok:
            problems.append("cites '%s \u00a7 %s', which is not a heading of that file" % (path, section))
    if re.search(r"master-prompt|f1-reference-gaps", source):
        cited = True
    if not cited:
        problems.append("has no pointer (f1-reference-gaps section, spec, ADR or test)")
    return problems


def provenance_errors(data):
    headings = f1_headings()
    errors = []

    def walk(node, path):
        if is_leaf(node):
            # The plugin group's sources are copied into compositor/src/core/ThemeTokens.hpp (compositor-owned): follow-up.
            if path[0] not in PLUGIN_GROUPS:
                for problem in source_problems(str(node.get("source", "")), headings):
                    errors.append(".".join(path) + " " + problem)
            return
        if isinstance(node, dict):
            for key, child in node.items():
                if not key.startswith("_") and isinstance(child, dict):
                    walk(child, path + [key])

    walk(data, [])
    return errors


def main():
    data = json.loads(SRC.read_text())
    unsourced = provenance_errors(data)
    if unsourced:
        print("gen-tokens: token sources that are not followable pointers:\n  " + "\n  ".join(unsourced), file=sys.stderr)
        return 1
    outputs = ((DST, generate(data), "ui/Grassfield/Ui/Tokens.qml"), (PLUGIN_DST, generate_plugin(data), "compositor/src/core/ThemeTokens.hpp"))
    if "--check" in sys.argv[1:]:
        stale = [label for path, text, label in outputs if not path.exists() or path.read_text() != text]
        for label in stale:
            print(f"gen-tokens: {label} is stale; run ui/tools/gen-tokens.py", file=sys.stderr)
        if stale:
            return 1
        print("gen-tokens: up to date")
        return 0
    for path, text, label in outputs:
        path.write_text(text)
        print(f"gen-tokens: wrote {label}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
